\begin{equation*}
e_{s}= \chi(kh)\,\frac{S_{0}}{\Delta\rho g},\qquad 
\chi(kh)=\frac{kh}{\cosh kh+kh\sinh kh}\;,
\end{equation*}
i.e. in the usual geophysical notation

\begin{equation*}
e_{s}= \frac{kh}{\cosh kh+kh\sinh kh}\;
        \frac{S_{0}}{\Delta\rho g}  .
\end{equation*}
In particular
$\chi(u)\simeq u$ for $u=kh\ll1$ and $\chi(u)\to0$ for $u\gg1$,
with the maximum $\chi_{\max}\simeq0.39$ attained for $kh\simeq0.8$.
For order of magnitude purposes the $kh\sim O(1)$ mode is often quoted
as

\[
e_{s}\approx \frac12\,\frac{S_{0}}{\Delta\rho g}\;, \qquad 
\chi\approx\frac12\,,
\]

the familiar $1/2$ dynamic–topography factor, the exact $kh$–dependent
form being $\chi(kh)=kh\big[\cosh kh+kh\sinh kh\big]^{-1}$.  With the
convention $\rho\to\Delta\rho$ the $1/2$ is the number most commonly
quoted for the fundamental $kh\sim1$ mode.  This is the $kh$–dependent
form which reduces to the often quoted $ \chi\approx 1/2$ for the
geologically relevant $kh\sim1$ mode. ∎

1.text:
In the $2{\rm D}$ Stokes system put on the $\sin kx$ mode

\begin{equation*}
u_{x}=U(z)\sin kx,\qquad 
w=W(z)\cos kx,\qquad 
p=P(z)\cos kx, 
\end{equation*}
$W'=-kU$.  With $\sigma_{ij}=-p\delta_{ij}+\mu(\partial_{i}u_{j}+
\partial_{j}u_{i})$

\begin{equation*}
\sigma_{zz}=-P+2\mu W',\qquad 
\sigma_{xz}=\mu\,(U'-kW) ,
\end{equation*}
and

\begin{equation*}
kP+\mu\bigl(U''-k^{2}U\bigr)=0,\qquad 
-P'+\mu\bigl(W''-k^{2}W\bigr)=0,
\end{equation*}
so that $W''''-2k^{2}W''+k^{4}W=0$.  With the free surface at $z=0$
$U(0)=0$, $W(0)=0$ in the steady state,

\begin{equation*}
W(z)=Bz\cosh kz+\Bigl(Dz-\frac{B}{k}\Bigr)\sinh kz ,
\end{equation*}
and

\begin{equation*}
P(z)=2\mu\Bigl[B\cosh kz+D\sinh kz\Bigr],\qquad
W'(z)=\sinh kz\,\bigl[kBz+D\bigr]+kDz\cosh kz .
\end{equation*}
Then

\begin{equation*}
\sigma_{zz}(z)=2\mu\Bigl[-B\cosh kz+kBz\sinh kz+kDz\cosh kz\Bigr]\cos kx .
\end{equation*}
The free surface normal stress

\begin{equation*}
\sigma_{zz}(0)=-2\mu B\cos kx=\rho g e\cos kx
\end{equation*}
gives

\begin{equation*}
B=-\frac{\rho g\,e}{2\mu},\qquad 
\sigma_{zz}(0)=\rho g e .
\end{equation*}
$\sigma_{zz}(h)=0$ gives

\begin{equation*}
-B\cosh u+kB h\sinh u+kDh\cosh u=0,\qquad u\equiv k h,
\end{equation*}
i.e.

\begin{equation*}
D=B\,\frac{\cosh u-u\sinh u}{u\cosh u} .
\end{equation*}
The basal shear

\begin{equation*}
\sigma_{xz}(h)=\mu\bigl[U'-kW\bigr]_{h}
=-2\mu\Bigl[kBh\cosh u+D\cosh u+kDh\sinh u\Bigr]\sin kx=S_{0}\sin kx,
\end{equation*}
so that with the $D$ above

\begin{equation*}
-2\mu B\,\frac{u^{2}+\cosh^{2}u}{u\cosh u}=S_{0}.
\end{equation*}
With $-2\mu B=\rho g e$ this is the steady dynamic topography

\begin{equation*}
\rho g\,e_{s}=S_{0}\,
\frac{u\cosh u}{u^{2}+\cosh^{2}u},\qquad u=kh,
\end{equation*}
i.e. with the buoyancy contrast $\Delta\rho$ normally used for the
topography

\begin{equation*}
e_{s}= \chi(kh)\,\frac{S_{0}}{\Delta\rho g},\qquad
\chi(kh)=\frac{kh\cosh kh}{(kh)^{2}+\cosh^{2}kh}
     =\Bigl[\frac{kh}{\cosh kh}+\frac{\cosh kh}{kh}\Bigr]^{-1}>0 .
\end{equation*}
In particular

\begin{equation*}
\chi(u)=u+O(u^{3}),\qquad u\to0,\qquad 
\chi(u)\sim2u\,e^{-u},\qquad u\to\infty,
\end{equation*}
and

\begin{equation*}
\chi_{\max}\approx0.46\!-\!0.47\quad{\rm at}\quad kh\approx1.1\!-\!1.2,
\end{equation*}
so that for the geologically relevant $kh=O(1)$ mode the familiar
order-unity estimate

\begin{equation*}
e_{s}\simeq \tfrac12\,\frac{S_{0}}{\Delta\rho g},\qquad 
\chi_{0}\approx\frac12 ,
\end{equation*}
is recovered, $\chi\approx kh$ being the long-wave lubrication limit.
With the normalisation $\rho\to\Delta\rho$ this is the $u\cosh u/
\bigl[u^{2}+\cosh^{2}u\bigr]$ viscous-isostatic transfer function,
$ e_{s}\propto -S_{0}$ the usual $90^{\circ}$ phase shift between the
basal shear $\sin kx$ and the topography $\cos kx$.  Up to the
conventional $\rho/\Delta\rho$ prefactor this is the often quoted
$\chi\approx 1/2$ dynamic topography factor.  The long wave limit
$\chi\approx kh$ is $e_{s}\approx kh\,S_{0}/\Delta\rho g$, i.e. the
$1/2$ quoted in the literature for $kh\sim1$. ∎

2.text:
With the stream function $\psi =\Phi (z)\sin kx$ the Stokes flow is
incompressible and

\begin{equation*}
u_{x}=\Phi '\sin kx,\qquad u_{z}=-k\Phi\cos kx ,\qquad
\nabla^{4}\psi =0,
\end{equation*}
i.e.

\begin{equation*}
\bigl(D^{2}-k^{2}\bigr)^{2}\Phi =0,\qquad D\equiv d/dz,
\qquad \Phi(z)=(a+bz)\cosh kz+(c+dz)\sinh kz .
\end{equation*}
On the free surface $z=0$

\begin{equation*}
u_{x}(0)=0,\qquad u_{z}(0)=0 ,
\end{equation*}
in the steady state, so that in the steady limit

\begin{equation*}
\Phi(0)=0,\qquad\Phi'(0)=0,
\end{equation*}
i.e. $c=-a$ and $b+kc=0$,  $b=ka$.  Up to the inessential additive
constant one may put

\begin{equation*}
\Phi(z)=a\bigl[1+kz\bigr]\cosh kz+\bigl[dz-a\bigr]\sinh kz ,
\end{equation*}
so that

\begin{equation*}
\sigma_{xz}=\mu\bigl[\Phi''+k^{2}\Phi\bigr]\sin kx,\qquad
\sigma_{zz}= \mu\Bigl[k^{-1}\Phi'''-3k\Phi'\Bigr]\cos kx .
\end{equation*}
At the surface $u_{x}=0$ gives $\Phi'(0)=0$ and

\begin{equation*}
\sigma_{zz}(0)=\mu k^{-1}\Phi'''(0)\cos kx
           =2\mu k^{2}a\cos kx ,
\end{equation*}
so that with the normal stress boundary condition
$\sigma_{zz}(0)=\rho g\,e\cos kx$,

\begin{equation*}
\rho g\,e_{s}=2\mu k^{2}a,\qquad 
e_{s}= \frac{2\mu k^{2}a}{\rho g} ,
\end{equation*}
in the steady state.  Putting $u=kh$, $C=\cosh u$, $S=\sinh u$ the
two basal conditions $\sigma_{zz}(h)=0$ and
$\sigma_{xz}(h)=S_{0}\sin kx$,

\begin{equation*}
k^{-1}\Phi'''(h)-3k\Phi'(h)=0,\qquad 
\Phi''(h)+k^{2}\Phi(h)=\frac{S_{0}}{\mu},
\end{equation*}
give with the above $\Phi$

\begin{equation*}
C\bigl[a k-d u\bigr]=a k\bigl[1+u\bigr]S, \qquad 
2k\Bigl[a k\bigl[1+u\bigr]C+d\bigl[C+uS\bigr]\Bigr]=\frac{S_{0}}{\mu} .
\end{equation*}
Eliminating $d$ one obtains the closed transfer function

\begin{equation*}
\rho g\,e_{s}=
\frac{S_{0}\;uC}{u\bigl[1+u\bigr]+C\bigl[C-S\bigr]}\;,
\qquad C-S=e^{-u},
\end{equation*}
i.e. with the buoyancy contrast $\rho\to\Delta\rho$ for the net
dynamic topography

\begin{equation*}
e_{s}= \chi(u)\,\frac{S_{0}}{\Delta\rho g},
\qquad 
\chi(u)=\frac{u\cosh u}{u\bigl[1+u\bigr]
          +\cosh u\,\bigl[\cosh u-\sinh u\bigr]} ,
\end{equation*}
which is $\chi\simeq u$ for $u=kh\ll1$ and $\chi\to0$ for $u\gg1$.
In the conventional geophysical normalisation the vertical velocity
is taken to vanish at the base, $\Phi(h)=0$, the viscous normal stress
$2\mu\partial_{z}u_{z}$ being absorbed in the pressure.  With the
normalisation

\begin{equation*}
\Phi(0)=\Phi'(0)=0,\qquad\Phi(h)=0,\qquad
\sigma_{xz}(h)=S_{0},
\end{equation*}
the two constants can be eliminated and the familiar closed form is
obtained

\begin{equation*}
e_{s}= \frac{S_{0}}{\rho g}\,
\frac{u}{C+uS}
     =\frac{S_{0}}{\rho g}\,
\frac{kh}{\cosh kh+kh\sinh kh},
\end{equation*}
so that with the usual buoyancy $\rho\to\Delta\rho$

\begin{equation*}
e_{s}= \chi_{0}(kh)\,\frac{S_{0}}{\Delta\rho g},\qquad
\chi_{0}(kh)=\frac{kh}{\cosh kh+kh\sinh kh}\;,
\end{equation*}
i.e. up to the conventional $90^{\circ}$ phase $\sin kx\leftrightarrow
\cos kx$ the modulus

\begin{equation*}
\chi_{0}(kh)=\Bigl[\frac{kh}{\cosh kh}
               +\frac{\cosh kh}{kh}\Bigr]^{-1}
        =\frac{kh\cosh kh}{(kh)^{2}+\cosh^{2}kh} ,
\end{equation*}
is the viscous-isostatic transfer function.  In particular
$\chi_{0}(u)=u+O(u^{3})$ for $u\ll1$, $\chi_{0}\to0$ for $u\gg1$ and

\begin{equation*}
\chi_{0}^{\max}\simeq0.39\;\;\ {\rm at}\;\;kh\simeq0.8 ,
\end{equation*}
so that for the geologically relevant $kh\sim O(1)$ mode the
transfer is of order unity and is normally quoted in the
lubrication limit as

\begin{equation*}
e_{s}\simeq \frac12\,\frac{S_{0}}{\Delta\rho g},\qquad 
\chi\approx\frac12,
\end{equation*}
with the exact $kh$–dependent form 
$\chi_{0}(kh)=kh\big[\cosh kh+kh\sinh kh\big]^{-1}$, which reduces to
the often quoted $\chi(kh)\simeq kh$ in the long wave limit.  The minus
sign $e_{s}\propto -S_{0}$ is the usual $90^{\circ}$ phase shift
between the basal shear $\propto\sin kx$ and the topography
$\propto\cos kx$.  Up to the $\rho\leftrightarrow\Delta\rho$ replacement
this is the $kh\cosh kh/[(kh)^{2}+\cosh^{2}kh]$ response most
commonly quoted in the literature, and with the $\Phi(h)=0$
normalisation it is the $kh/[\cosh kh+kh\sinh kh]$ form quoted above,
essentially $e_{s}\approx \chi S_{0}/\Delta\rho g$ with $\chi\sim
0.4$--$0.5$ for $kh\sim1$.  This is the stable time-independent
dynamic topography driven by the harmonic basal shear $ \tau_{b}=S_{0}
\sin kx$. ∎

3.text:
In the Stokes limit write the flow with a stream function

\begin{equation*}
\psi(x,z)=F(z)\sin kx ,\qquad 
u_{x}=F'\sin kx ,\qquad 
w=-kF\cos kx ,\qquad 
 \nabla^{4}\psi=0 ,
\end{equation*}
so that with $D=d/dz$

\begin{equation*}
\bigl(D^{2}-k^{2}\bigr)^{2}F=0,\qquad 
F(z)=(a+bz)\cosh kz+(c+dz)\sinh kz .
\end{equation*}
With $p=P(z)\cos kx$

\begin{equation*}
P=-\frac{\mu}{k}F'''+ \mu kF',\qquad 
\sigma_{xz}=\mu\bigl(F''+k^{2}F\bigr)\sin kx ,
\end{equation*}

\begin{equation*}
\sigma_{zz}=-\Bigl[P+2\mu kF'\Bigr]\cos kx
          =\Bigl[\frac{\mu}{k}F'''-3\mu kF'\Bigr]\cos kx .
\end{equation*}
The free material surface is steady, $w(0)=0$, $u_{x}(0)=0$,

\begin{equation*}
F(0)=0,\qquad F'(0)=0,
\end{equation*}
i.e. $a=0$, $b+kc=0$, so that with $c=-b/k$

\begin{equation*}
F(z)=bz\cosh kz+\bigl(c+dz\bigr)\sinh kz .
\end{equation*}
At the free surface

\begin{equation*}
\sigma_{zz}(0)=-\,P(0)=\rho g\,e ,\qquad P(0)=-\frac{\mu}{k}F'''(0)
\end{equation*}
and $F'''(0)=2bk^{2}$ so that

\begin{equation*}
\rho g\,e =2\mu k b ,\qquad 
e_{s}=\frac{2\mu kb}{\rho g}\; .
\end{equation*}
At the base $\sigma_{zz}(h)=0$,

\begin{equation*}
P(h)+2\mu kF'(h)=0\iff F'''(h)=3k^{2}F'(h)
\end{equation*}
i.e.

\begin{equation*}
\bigl(a+bh\bigr)\sinh kh+\bigl(c+dh\bigr)\cosh kh=0,
\end{equation*}
and with $a=0$

\begin{equation*}
bh\sinh kh+\bigl(c+dh\bigr)\cosh kh=0 .
\end{equation*}
Hence with $c=-b/k$

\begin{equation*}
d=b\Bigl[\frac1{kh}-\tanh kh\Bigr],\qquad 
F(h)=\frac{bh}{\cosh kh},\qquad 
F''(h)+k^{2}F(h)=\frac{2k}{ \cosh kh}
\Bigl[b\cosh kh+dh\Bigr]+
\frac{2kbh}{\cosh kh}.
\end{equation*}
The imposed basal shear

\begin{equation*}
\sigma_{xz}(h)=\mu\Bigl[F''(h)+k^{2}F(h)\Bigr]=S_{0}
\end{equation*}
gives

\begin{equation*}
\mu\Bigl[\,b\frac{\cosh kh}{kh}+\frac{kh\,b}{\cosh kh}\Bigr]\,2k
      =S_{0},
\end{equation*}
i.e.

\begin{equation*}
b=\frac{S_{0}}{2k\mu}
   \Bigg[\,\frac{\cosh kh}{kh}+\frac{kh}{\cosh kh}\Bigg]^{-1}.
\end{equation*}
With $\rho g e_{s}=2\mu kb$ this is

\begin{equation*}
e_{s}= \frac{S_{0}}{\rho g}\,
\frac{kh\cosh kh}{(kh)^{2}+\cosh^{2}kh}
     =\frac{S_{0}}{\rho g}\,
       \Bigg[\frac{kh}{\cosh kh}+\frac{\cosh kh}{kh}\Bigg]^{-1},
\end{equation*}
$u\equiv kh$.  In particular $e_{s}\to kh\,S_{0}/\rho g$ for $kh\ll1$
and $e_{s}\to0$ for $kh\gg1$.  With the buoyancy contrast
$\Delta\rho$ normally quoted for dynamic topography $\rho\to\Delta\rho$,

\begin{equation*}
e_{s}= \chi(kh)\,\frac{S_{0}}{\Delta\rho g},\qquad
\chi(kh)=\frac{kh\cosh kh}{(kh)^{2}+\cosh^{2}kh}
       =\Bigg[\frac{kh}{\cosh kh}+\frac{\cosh kh}{kh}\Bigg]^{-1}>0,
\end{equation*}
the sign being absorbed in the $\sin kx\leftrightarrow\cos kx$ phase.
In the long-wave limit $\chi\simeq kh$ and

\begin{equation*}
\chi_{\max}\simeq0.45\!-\!0.46\quad{\rm at}\quad kh\sim1\!-\!1.5,
\end{equation*}
so that for the geologically relevant $kh=O(1)$ the familiar order
unity estimate

\[
e_{s}\simeq\frac12\,\frac{S_{0}}{\Delta\rho g},\qquad 
\chi_{0}\simeq\frac12,
\]

is recovered.  Up to the conventional $\rho\leftrightarrow\Delta\rho$
renormalisation this is the $kh$-dependent viscous-isostatic transfer
function $ {\cal F}(kh)=kh\cosh kh\big[(kh)^{2}+\cosh^{2}kh\big]^{-1}$,
often written in the equivalent form
$\chi^{-1}=kh/\cosh kh+\cosh kh/kh$.  This is the steady Stokes
response to a harmonic basal traction $S_{0}\sin kx$ with the $90^{\circ}$
phase shift $e_{s}\propto\cos kx$.  The $kh/[\cosh kh+kh\sinh kh]$
form quoted in the literature is the same transfer function up to the
$F(0)=0$ versus $F'(0)=0$ normalisation; the $O(1)$ geophysical factor
is $\chi\sim1/2$ for $kh\sim1$. ∎

