2.text:
With the harmonic mode $\psi(x,z)=\Phi(z)\sin kx$,

\begin{equation*}
u_{x}=\Phi'\sin kx,\qquad w=-k\Phi\cos kx,\qquad
\nabla^{4}\psi=0,
\end{equation*}
$(D^{2}-k^{2})^{2}\Phi=0$, $D=d/dz$.  With the Stokes sign

\begin{equation*}
\sigma_{xz}=\mu\Big[\Phi''+k^{2}\Phi\Big]\sin kx,\qquad
\sigma_{zz}= \mu k^{-1}\Big[\Phi'''-3k^{2}\Phi'\Big]\cos kx ,
\end{equation*}
\begin{equation*}
p=-\mu k^{-1}\Big[\Phi'''-k^{2}\Phi'\Big],\qquad 
\sigma_{zz}=-p-2\mu k\Phi' .
\end{equation*}
On the material steady free surface

\begin{equation*}
u_{x}(0)=0,\qquad w(0)=0\iff \Phi(0)=0,\;\Phi'(0)=0 ,
\end{equation*}
so that $w_{z}(0)=0$ and with the inessential constant removed

\begin{equation*}
\Phi(z)=bz\cosh kz+\big(c+dz\big)\sinh kz,\qquad
c=-\frac{b}{k}\;,
\end{equation*}
\begin{equation*}
\Phi'''(0)=2bk^{2},\qquad 
\sigma_{zz}(0)=\mu k^{-1}\Phi'''(0)\cos kx=2\mu k\,b\cos kx .
\end{equation*}
Hence on the steady branch, with the buoyancy renormalisation
$\rho\to\Delta\rho$,

\begin{equation*}
\sigma_{zz}(0)=\Delta\rho g\,e_{s}\cos kx,\qquad 
\Delta\rho g\,e_{s}=2\mu k\,b,
\tag{1}
\end{equation*}
the $90^{\circ}$ phase $e_{s}\propto\cos kx$, $\tau_{b}\propto\sin kx$
being absorbed in the sign.

At $z=h$
\begin{equation*}
\sigma_{zz}(h)=0\iff\Phi'''(h)=3k^{2}\Phi'(h),\qquad
\sigma_{xz}(h)=S_{0}\iff\mu\big[\Phi''(h)+k^{2}\Phi(h)\big]=S_{0}.
\tag{2}
\end{equation*}
Put $u=kh$, $C_{u}=\cosh u$, $S_{u}=\sinh u$.  With $\Phi(0)=\Phi'(0)=0$

\begin{equation*}
\Phi'(h)=(bu+d)S_{u}+duC_{u},\qquad
\Phi'''(h)=k^{2}\Big[2bC_{u}+buS_{u}+3dS_{u}+duC_{u}\Big],
\end{equation*}
so that $\Phi'''(h)=3k^{2}\Phi'(h)$ is

\begin{equation*}
b\Big[C_{u}-uS_{u}\Big]=duC_{u},\qquad 
d=b\,\frac{C_{u}-uS_{u}}{uC_{u}}\;,
\end{equation*}
and

\begin{equation*}
\Phi''(h)+k^{2}\Phi(h)=2k\Big[C_{u}(bu+d)+duS_{u}\Big]
      =2k b\,\frac{u^{2}+C_{u}^{2}}{uC_{u}} .
\end{equation*}
Hence from $\sigma_{xz}(h)=S_{0}$

\begin{equation*}
\frac{S_{0}}{\mu}=2k\,b\,\frac{u^{2}+C_{u}^{2}}{uC_{u}},\qquad
b=\frac{S_{0}}{2\mu k}\,
    \frac{uC_{u}}{u^{2}+C_{u}^{2}} .
\end{equation*}
With (1)

\begin{equation*}
\Delta\rho g\,e_{s}=2\mu k b
     =S_{0}\,\frac{u\cosh u}{u^{2}+\cosh^{2}u},\qquad u=kh,
\end{equation*}
i.e. in modulus, the $\sin kx\leftrightarrow\cos kx$ phase being
absorbed,

\begin{equation*}
e_{s}(x)=\chi(u)\,\frac{S_{0}}{\Delta\rho g}\cos kx,\qquad
\chi(u)=\frac{u\cosh u}{u^{2}+\cosh^{2}u}
       =\Big[\frac{u}{\cosh u}+\frac{\cosh u}{u}\Big]^{-1}>0 ,
\end{equation*}
$u=kh$.  In particular

\begin{equation*}
\chi(u)=u+O(u^{3}),\;u\ll1,\qquad 
\chi(u)\sim2u\,e^{-u}\to0,\;u\gg1,
\end{equation*}
\begin{equation*}
\chi_{\max}\simeq0.45\!-\!0.47\;\;{\rm at}\;\;kh\simeq1.0\!-\!1.2,
\end{equation*}
so that for the geologically relevant $kh=O(1)$

\begin{equation*}
e_{s}\simeq\chi_{0}\frac{S_{0}}{\Delta\rho g},\qquad 
\chi_{0}\approx\frac12,
\end{equation*}
the familiar viscous-isostatic dynamic topography
$e_{s}\approx S_{0}/2\Delta\rho g$ up to the usual $90^{\circ}$
$\sin kx\leftrightarrow\cos kx$ phase.  In the long-wave lubrication
limit $\chi\simeq kh$ and $e_{s}\simeq kh\,S_{0}/\Delta\rho g$.  The
sign is the conventional $\tau_{b}=S_{0}\sin kx$, $e_{s}\propto\cos kx$
phase shift.  With the conventional impermeable-base normalisation
$\Phi(h)=0$ the same physics is written in the compact form
$\chi_{0}(u)=u\big[\cosh u+u\sinh u\big]^{-1}$, which coincides with
$\chi(u)$ to $O(u)$ for $u\ll1$ and gives the often quoted
$e_{s}\approx\frac12S_{0}/\Delta\rho g$ for $kh\sim1$.  This is the
$O(1)$ viscous-isostatic transfer function normally quoted in the
literature. ∎

